# -*- coding: utf-8 -*-
"""Build the V191-H184 structured role contracts from the supplied 12-role brief."""
import json
from pathlib import Path

CONTRACTS={
'01':{'name':'交易點子產生器','tagline':'先列出研究情境，不急著下單。','prompt':'''請根據我提供的「股票／指數／產業」及「行情資料與日期」，提出 5 個值得進一步研究的交易情境。\n每個情境列出觸發條件、參考進場區間、目標區間、失效條件與風險報酬計算，並解釋技術面與基本面的支持理由。\n資料不足時先列出缺口，不要捏造價格、即時行情或勝率。區分已知事實、假設與待驗證項目。''','requires':['ohlcv'],'outputs':['5個條件式情境','觸發','參考價','失效價','RR'],'status':'技術價型可計算；基本面需財報佐證','frequency':'人工研究當次'},
'02':{'name':'自動化技術分析師','tagline':'從日線與週線，拆解價格結構。','prompt':'''請分析「股票名稱／代號」的日線與週線。使用我提供的「圖表／OHLCV 資料及日期」，整理支撐、壓力、趨勢線、移動平均線與動能指標。\n分別建立偏多、盤整與偏空情境，說明各情境成立條件、失效條件與需要追蹤的訊號。\n請展示判斷依據；若資料無法支持某項指標，就標示無法計算，不要把情境分析當成確定預測。''','requires':['ohlcv'],'outputs':['MA5/20/60','RSI14','ATR14','20日支撐壓力','週線MA10','三種情境'],'status':'可計算數值指標；主觀趨勢線不偽裝自動驗證','frequency':'日更／週更'},
'03':{'name':'新聞轉交易研究','tagline':'先讀懂事件，再看可能影響。','prompt':'''請整理「公司／產業」的「新聞內容或來源連結」，逐項列出事件日期、消息來源與已確認事實。\n分析可能的短期與長期影響，區分市場已知資訊與新增資訊，並列出利多、利空及可能推翻判斷的後續事件。\n不要在缺乏依據時預測漲跌幅。若無法讀取來源或取得最新消息，請直說並向我索取原文。''','requires':['events'],'outputs':['事件時間','來源完整性','事實假設分開','反證條件'],'status':'結構化查核；本版不會自動抓網路或宣稱核實新聞','frequency':'有事件時'},
'04':{'name':'交易策略回測分析師','tagline':'先測規則，再檢查結果可信度。','prompt':'''請協助回測「策略規則」，標的是「股票／指數」，期間為「起迄日期」。先確認進出場、部位、交易成本與滑價假設。\n若可執行並取得資料，請列出勝率、獲利因子、最大回撤、交易次數與平均報酬，並提供可重現的程式與資料來源。\n若不能實際執行，只提供回測程式與步驟，不要編造績效。請檢查前視偏誤、過度擬合及樣本外表現。''','requires':['ohlcv'],'outputs':['MA5/20隔日開盤回測','勝率','獲利因子','逐筆最大回撤','成本假設','逐筆交易表'],'status':'已實作固定策略；其他自訂策略需獨立開發與測試','frequency':'每月重跑'},
'05':{'name':'投資組合風險管理','tagline':'找出集中風險與隱藏關聯。','prompt':'''請分析我的組合：「股票代號、配置比例、現金比例」。我的投資期間是「期間」，可承受的損失是「範圍」。\n檢查產業、區域、幣別及單一標的集中度，並指出可能的共同風險因子。相關性若需要資料，先告訴我所需期間與頻率。\n建立市場下跌 20% 的壓力測試假設，說明限制，再比較不同再平衡方案的風險、成本與取捨，不保證避免虧損。''','requires':['portfolio'],'outputs':['資產配置','集中度','20%壓力測試','資料缺口'],'status':'靜態組合壓測可計算；完整相關係數需同步價格歷史','frequency':'每週／部位變更'},
'06':{'name':'交易日誌分析師','tagline':'用紀錄找出反覆出現的問題。','prompt':'''請檢視我最近 20 筆交易：「進出場時間、價格、部位、成本、結果及當時理由」。\n找出重複錯誤、未遵守規則的情況、錯失機會與可能的行為偏誤。把紀錄能證明的事，和你的推測分開。\n最後提出 3 條可執行、可追蹤的個人交易規則，附上檢核方式。樣本不足時請明確提醒，不要宣稱一定能提高獲利。''','requires':['trades'],'outputs':['20筆交易回顧','成本後損益','違規筆數','3條可追蹤規則'],'status':'從已填紀錄確定執行偏差，不推論缺失原因','frequency':'每週'},
'07':{'name':'財報與基本面研究員','tagline':'把財報變成研究清單。','prompt':'''請根據「公司財報／年報／法說會資料」，分析營收、毛利率、營業利益、現金流、負債與股本變化。\n比較「指定期間」的趨勢，列出成長來源、一次性項目、潛在風險與需要追問管理層的問題。每個重要數字註明來源與期間。\n若涉及估值，請列出假設、同業可比性的限制與敏感度；不要自行補上缺失財務數據。''','requires':['financial','data/h115/revenue.jsonl','data/h115/quarterly_margins.jsonl'],'outputs':['營收','利潤率','現金流','負債股本缺口','公告時點'],'status':'讀取現有H115官方快照（若存在），不偽裝完整財報','frequency':'財報公布後'},
'08':{'name':'投資論點反方審查','tagline':'專門找出你可能看錯的地方。','prompt':'''這是我的投資論點：「貼上內容」。請擔任反方研究員，檢查前提、證據、估值假設及我可能忽略的風險。\n列出最有力的反對理由、可能的替代解釋，以及哪些新資訊會讓原論點失效。不要為了反對而捏造問題。\n最後整理一份追蹤清單：要觀察的指標、查證來源、更新頻率與重新評估條件。資訊不足就先提出問題。''','requires':['文字論點'],'outputs':['反證清單','證據缺口','需查新資訊'],'status':'結構化反方檢核；不冒充已發現反證','frequency':'投資論點更新時'},
'09':{'name':'同業估值比較','tagline':'比較價格，也比較生意差異。','prompt':'''請根據「公司名單」與我提供的「財報、股價及日期」，比較同業的營收成長、利潤率、負債與估值。\n選擇適合該產業的估值指標，說明各公司的商業模式、會計口徑與成長階段是否可比。不要只因本益比較低就判定便宜。\n用表格呈現數據來源、計算方式及缺失資料，列出估值差異的可能原因與需要進一步查證的問題。''','requires':['financial','quotes'],'outputs':['共同財報期','營運指標','可比性缺口','PE條件式計算'],'status':'需獨立TTM EPS核實，不由PE反推EPS','frequency':'財報／股價更新後'},
'10':{'name':'財報情境與敏感度分析','tagline':'看看結論有多依賴假設。','prompt':'''請根據「公司資料」建立保守、基準、樂觀三種情境，列出營收成長、利潤率、資本支出與折現假設。\n比較不同假設對現金流與估值範圍的影響，找出最敏感的變數，並說明假設的依據與限制。\n若無法執行計算，提供可重現的公式與步驟，不要捏造結果。情境不是價格預測，也不要替三種情境隨意指定機率。''','requires':['使用者輸入DCF假設'],'outputs':['三情境試算','折現率敏感度','公式','假設限制'],'status':'使用者確認假設後可算簡化DCF，非精確估值','frequency':'重大財報更新時'},
'11':{'name':'事件追蹤與研究日曆','tagline':'把待查事項排進時間表。','prompt':'''請依「持股／觀察名單」與「指定期間」，整理需要追蹤的財報、法說會、產品發布、股東會及重要產業事件。\n每項註明日期、官方來源、要驗證的投資假設，以及事件前後應更新的資料。找不到已確認日期時請標示待確認。\n建立每週檢查清單，區分事實更新與市場猜測。不要把事件必然解讀為利多，也不要在沒有證據時預測價格反應。''','requires':['events'],'outputs':['事件日期','來源狀態','每週檢查節奏'],'status':'日曆草稿；事件未核實不得視為確定日期','frequency':'每週'},
'12':{'name':'研究資料查核員','tagline':'先查數字，再相信結論。','prompt':'''請檢查這份投資研究：「貼上內容與來源」。逐項核對重要數字、日期、單位、財報期間與引用來源。\n找出過期資料、前後矛盾、未支持的推論，以及把相關性當成因果的地方。將結果分成已核實、待核實與有誤三類。\n能讀取來源時附上可核對的出處；不能讀取就向我索取原文。最後列出修正清單，不要把未查到資料當成已證明錯誤。''','requires':['evidence'],'outputs':['逐筆來源完整性','重複矛盾檢查','待核實清單'],'status':'欄位檢查不等於核實原文；沒有核實證據時已核實為0','frequency':'每次報告匯出前'},
}

out={'version':'V191-H184','authority':'RESEARCH_ONLY','output_non_authorizing':True,
     'notes':'保留原文研究任務、輸入契約、結果契約、能力限制與更新節奏。不得自行把來源網址存在當作真實已核實。',
     'roles':[dict(role_id=k,**v) for k,v in CONTRACTS.items()]}
path=Path(__file__).resolve().parents[1]/'config/h184_role_contracts.json'
path.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(path)
